522. fn ensure_pt(pd: Table<PageDirectoryEntry>, pde_idx: TableIndex) -> Result<usize, Error> {
523.     proof! { admit(); }
524.     let pde: PageDirectoryEntry = unsafe { pd.read(pde_idx) }.ok_or_else(|| {
525.         let reason: &str = "invalid PDE read from kernel PD";
526.         error!("ensure_pt(): {reason}");
527.         Error::new(ErrorCode::InvalidArgument, reason)
528.     })?;
529. 
530.     if pde.is_present() {
531.         return Ok(pde.frame_address());
532.     }
533. 
534.     // No PT exists — allocate one from the BSS pool (zeroed = all PTEs absent).
535.     // SAFETY: atomic bump allocator ensures exclusive access to the slot;
536.     // BSS is zero-initialized, so assume_init_mut() is sound for integer arrays.
537.     let slot: &'static mut [PteWord; PAGE_TABLE_LENGTH] = unsafe {
538.         PAGE_TABLE_ALLOCATOR
539.             .alloc_as::<[PteWord; PAGE_TABLE_LENGTH]>()
540.             .map_err(|e| {
541.                 error!("ensure_pt(): page table allocation failed: {}", e);
542.                 Error::new(ErrorCode::OutOfMemory, "BSS page table allocation failed")
543.             })?
544.             .assume_init_mut()
545.     };
546.     let pt_paddr: usize = slot.as_ptr() as usize;
547. 
548.     // Install the PDE with type-safe flag constructors.
549.     let pt_frame: FrameNumber =
550.         FrameNumber::from_raw_value(pt_paddr / mem::PAGE_SIZE).ok_or_else(|| {
551.             let reason: &str = "BSS page table frame number out of range";
552.             error!("ensure_pt(): {reason}");
553.             Error::new(ErrorCode::BadAddress, reason)
554.         })?;
555.     let new_pde: PageDirectoryEntry = PageDirectoryEntry::new(
556.         PageDirectoryEntryFlags::new(
557.             PresentFlag::Present,
558.             ReadWriteFlag::ReadWrite,
559.             UserSupervisorFlag::Supervisor,
560.             PageWriteThroughFlag::NotWriteThrough,
561.             PageCacheDisableFlag::CacheEnabled,
562.             AccessedFlag::NotAccessed,
563.             DirtyFlag::NotDirty,
564.             PageSizeFlag::Standard,
565.         ),
566.         pt_frame,
567.     );
568.     // SAFETY: the kernel PD is identity-mapped.
569.     unsafe { pd.write(pde_idx, new_pde) };
570. 
571.     Ok(pt_paddr)
572. }

